# AtomicAndPhysicalConstants/src/CODATA2002.jl
# Constants pulled from the NIST table of
# the 2002 CODATA release
# Generated by update/update_constants.jl; masses are NIST's
# "energy equivalent in MeV" values with the decimal point moved to eV.



#####################################################################
# Physical constants
#####################################################################


"""
    CODATA2002 :: CODATA_release

Fundamental constants from the 2002 CODATA release.

See [NIST CODATA](https://physics.nist.gov/cuu/Constants/) for the
primary source values.
"""
const CODATA2002 = CODATA_release(

#######################################
# constants with dimension [mass]
#######################################


M_ELECTRON = 510998.918,
# Electron Mass [eV]/c^2
M_PROTON = 9.38272028e8,
# Proton Mass [eV]/c^2
M_NEUTRON = 9.3956536e8,
# Neutron Mass [eV]/c^2
M_MUON = 1.056583692e8,
# Muon Mass [eV]/c^2
M_HELION = 2.80839142e9,
# Helion Mass He3 nucleus [eV]/c^2
M_DEUTERON = 1.87561282e9,
# Deuteron Mass [eV]/c^2
M_TRITON = NaN,
# not tabulated in the 2002 release
# Triton Mass [eV]/c^2

# not tabulated by CODATA; fit values from the 2002 edition of the
# PDG Review of Particle Physics
M_PION_0 = 1.34976617572303e8,
# uncharged pion mass [eV]/c^2
M_PION_CHARGED = 1.39570180788299e8,
# charged pion mass [eV]/c^2


#######################################
# constants with dimension [magnetic moment]
#######################################


MU_DEUTERON_SI = 4.33073482e-27,
# deuteron magnetic moment in [J/T]
MU_ELECTRON_SI = -9.28476411e-24,
# electron magnetic moment in [J/T]
MU_HELION_SI = NaN,
# not tabulated in the 2002 release
# helion magnetic moment in [J/T]
MU_MUON_SI = -4.49044799e-26,
# muon magnetic moment in [J/T]
MU_NEUTRON_SI = -9.6623645e-27,
# neutron magnetic moment in [J/T]
MU_PROTON_SI = 1.41060671e-26,
# proton magnetic moment in [J/T]
MU_TRITON_SI = NaN,
# not tabulated in the 2002 release
# triton magnetic moment in [J/T]


#######################################
# dimensionless constants
#######################################


AVOGADRO = 6.0221415e23,
# Avogadro's constant: Number / mole (exact)
FINE_STRUCTURE = 0.007297352568,
# fine structure constant

ANOMALY_ELECTRON = 0.0011596521859,
# electron magnetic moment anomaly
ANOMALY_MUON = 0.00116591981,
# muon magnetic moment anomaly

G_DEUTERON_NUCLEAR_MAGNETON = NaN,
# not tabulated in the 2002 release
# deuteron g factor
G_ELECTRON = -2.0023193043718,
# electron g factor
G_HELION_NUCLEAR_MAGNETON = NaN,
# not tabulated in the 2002 release
# helion g factor
G_MUON = -2.0023318396,
# muon g factor
G_NEUTRON_NUCLEAR_MAGNETON = -3.82608546,
# neutron g factor
G_PROTON = 5.585694701,
# proton g factor
G_TRITON_NUCLEAR_MAGNETON = NaN,
# not tabulated in the 2002 release
# triton g factor


#######################################
# constants with miscellaneous dimension
#######################################


E_CHARGE = 1.60217653e-19,
# elementary charge [C]
R_ELECTRON = 2.817940325e-15,
# classical electron radius [m]
R_PROTON = 1.5346982688303786e-18,
# classical proton radius [m], R_ELECTRON * M_ELECTRON / M_PROTON
C_LIGHT = 2.99792458e8,
# speed of light [m/s]
H_PLANCK = 4.13566743e-15,
# Planck's constant [eV*s]
H_BAR = 6.58211915e-16,
# h_planck/twopi [eV*s]

K_BOLTZMANN = 8.617343e-5,
#k_B in eV/K

EPS_0 = 5.526349719790483e7,
# Permittivity of free space in [1/(eV*m)]
MU_0 = 2.0133544065607947e-25,
# Vacuum permeability in [eV*s^2/m]


G_PER_AMU = 1.66053886e-24,
# grams per standard atomic mass unit (dalton)

EV_PER_AMU = 9.31494043e8,
# eV/c^2 per standard atomic mass unit (dalton)

J_PER_EV = 1.60217653e-19,
# Joules per eV

EV_PER_J = 6.24150947e18,
# eV per Joule

G_PER_EV = 1.78266181e-33,
# grams per eV/c^2

RELEASE_YEAR = 2002


)

